/*
* 黑白杂志 - 酒馆移动端主题美化（推荐纯黑色背景）
* 代码来源：基于墨千尾老师的css代码，部分来自dc教程区的老师们，太多了尽量标注上。
* 二创作者：玲
* 素材均为ai生成（有他人生成也有自己生成）。
* 代码很⑩山，不会的部分可以问ai
* 有🛑是可以自定义的部分，如果要调适配可以看💖部分，基本只在代码上半部分
*/
/*字体🛑这代码被我破坏了，要换的删掉链接1就行*/
@import url("https://fontsapi.zeoseven.com/7/main/result.css");

body {
    font-family: "Zhuque Fangsong (technical preview)";
    font-weight: normal;
}
/* === 一、全局控制 === */
:root {
  /* 主要颜色变量 */
  --main-text-color: #000000; /* 主要文字颜色 */


  --shadow-color: transparent; /* 文字阴影颜色 */
  --chat-tint-color: transparent; /* 聊天区域背景颜色 */
  --blur-tint-color: rgba(255, 255, 255, 0.1); /* 毛玻璃背景颜色 */
  --border-color: rgba(255, 255, 255, 1); /* 边框颜色 */
  --user-mes-blur-tint-color: transparent; /* 用户聊天气泡背景 */
  --bot-mes-blur-tint-color: transparent; /* AI聊天气泡背景 */
  --blur-strength: 0px; /* 背景模糊强度 */
  --message-bg-alpha: 0; /* 消息背景透明度 */


  /* 💖含白色渐变伪元素独立控制 */
  --pseudo-top: 0px; /* 伪元素顶部位置 */
  --pseudo-left: 0px; /* 伪元素水平位置 */
  --pseudo-width: 396px; /* 🛑伪元素宽度-左右偏移了调这里 */
  --pseudo-height: 300px; /* 🛑伪元素高度 */
  --pseudo-scale: 1; /* 伪元素缩放 */

  /* 头像在伪元素内定位💖 */
  --avatar-top: 39.2%; /* 头像在伪元素内的垂直位置 - 头像跑出背景图调这里 */
  --avatar-left: 70.3%; /* 头像在伪元素内的水平位置 */
  --avatar-scale: 3; /* 头像缩放 */

  /* 每个信息元素独立位置变量💖垂直位置一般一样就行 */
  --mes-timer-top: 228px; /* 计时器垂直位置 */
  --mes-timer-left: 45px; /* 计时器水平位置 */
  --token-top: 228px; /* Token计数垂直位置 */
  --token-left: 78px; /* Token计数水平位置 */
  --mesid-top: 228px; /* 楼层数垂直位置 */
  --mesid-left: 17px; /* 楼层数水平位置 */
}

/* === 二、顶栏美化 === */
#top-settings-holder {
  background-image: url('https://iili.io/fYXieRe.png'); /* 顶栏背景图 */
  background-size: 100% 100%; /* 背景图尺寸 */
  background-position: center; /* 背景图位置 */
  background-color: rgba(255, 255, 255, 0); /* 背景底色透明，可以通过ui背景调色 */
  box-shadow: none; /* 无阴影 - 已修复 */
  border-bottom: 0px solid #ffffff; /* 底部边框 */
}

/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
  content: '' !important; /* 清空原有内容 */
  visibility: hidden; /* 隐藏元素 */
}
/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
  content: '' !important; /* 清空原有内容 */
  visibility: hidden; /* 隐藏元素 */
}

#top-settings-holder .drawer {
  flex: 1px; /* 🛑弹性布局-一个改成0很好玩的东西 */
}

#top-settings-holder .drawer-icon {
  display: block; /* 块级显示 */
  margin: 0 auto; /* 水平居中 */
  margin-top: 8px; /* 顶部间距 */
  background-size: contain; /* 背景图适应 */
  background-position: center; /* 背景图居中 */
  background-repeat: no-repeat; /* 不重复背景 */
  transition: all 0.3s ease-in-out; /* 过渡动画 */
  width: 15px; /* 图标宽度 */
  height: 15px; /* 图标高度 */
  opacity: 0.9 !important; /* 完全不透明 */
}

/* 顶栏图标替换，图标丢失我也不会，可以开开发者工具看类名问ai，或者用我其他美化的图标 */
.drawer-icon.fa-sliders { background-image: url('https://iili.io/fYXsNBR.png'); } /* AI响应配置 */
.drawer-icon.fa-plug { background-image: url('https://iili.io/fYXbukB.png'); } /* API连接 */
.drawer-icon.fa-font { background-image: url('https://iili.io/fYXb6Qe.png'); } /* AI回复格式化 */
.drawer-icon.fa-book-atlas { background-image: url('https://iili.io/fYh9Jn9.png'); } /* 世界信息 */
.drawer-icon.fa-user { background-image: url('https://iili.io/fYXyfII.png'); } /* 💖用户设置-一般丢失的是这个 */
.drawer-icon.fa-image { background-image: url('https://iili.io/fYh9AFa.png'); } /* 💖背景图-一般丢失的是这个 */
.drawer-icon.fa-cubes { background-image: url('https://iili.io/fYh9OtS.png'); } /* 扩展 */
.drawer-icon.fa-bars-progress { background-image: url('https://iili.io/fYXbukB.png'); } /* 记忆表格 */
.drawer-icon.fa-face-smile { background-image: url('https://iili.io/fYXb6Qe.png'); } /* 用户角色管理 */
.drawer-icon.fa-address-card { background-image: url('https://iili.io/fYXsNBR.png'); } /* 角色卡 */
/* 强制清除顶栏及父容器的黑色阴影 */
#top-settings-holder,
#top-bar, /* 顶栏父容器 */
.header-container, /* 可能的外层容器 */
.nav-bar { /* 通用导航栏容器 */
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    filter: drop-shadow(0 0 0 transparent) !important;
}
/* ===== 2. 点击后图标 ===== */
.drawer-icon.fa-sliders:hover,
.drawer-icon.fa-plug:hover,
.drawer-icon.fa-font:hover,
.drawer-icon.fa-book-atlas:hover,
.drawer-icon.fa-user:hover,
.drawer-icon.fa-image:hover,
.drawer-icon.fa-cubes:hover,
.drawer-icon.fa-bars-progress:hover,
.drawer-icon.fa-face-smile:hover,
.drawer-icon.fa-address-card:hover {
  background-image: url('https://iili.io/fYhouzg.png'); 

}

/* === 三、底栏美化 === */
/* 隐藏所有原始图标的伪元素 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none !important; /* 隐藏元素 */
}

/* 统一设置所有图标按钮样式 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  width: 20px; /* 图标宽度 */
  height: 20px; /* 图标高度 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
  transition: transform 0.2s ease; /* 过渡动画 */
  font-size: 0; /* 隐藏文本 */
  border: none; /* 无边框 */
  background-color: transparent; /* 透明背景 */
}

/* 悬停效果 */
#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#quick-reply-rocket-button:hover {
  transform: scale(1.1); /* 悬停放大 */
}

/* 分别设置每个按钮背景图片 */
#options_button { background-image: url('https://iili.io/fYhJMvf.png'); } /* 菜单按钮 */
#extensionsMenuButton { background-image: url('https://iili.io/fYhJMvf.png'); } /* 扩展按钮 */
#send_but { background-image: url('https://iili.io/fYhJMvf.png'); } /* 发送按钮 */
/* 💖图标3: QR助手 - 好像没啥用你们拿链接去qr助手换就行*/
#quick-reply-rocket-button i::before {
  content: 'https://iili.io/fYhJMvf.png' !important; 
}


/* 停止图标美化 */
#mes_stop {
  font-size: 0 !important; /* 隐藏文本 */
  width: 15px; /* 图标宽度 */
  height: 15px; /* 图标高度 */
  background-image: url('https://iili.io/fYhdQx2.png'); /* 停止图标 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
}

/* 底栏悬浮效果 */
#form_sheld {
  position: absolute; /* 绝对定位 */
  bottom: -1px; /* 底部间距 */
}

#send_form {
  width: 100%; /* 底栏宽度 */
}

.last_mes {
  margin-bottom: 150px !important; /* 最后消息底部间距 */
}

/* 底栏样式 */
#send_form, body.no-blur #send_form {
background-image: url('none'); /* 背景图 */
  background-size: 100% 100%; /* 背景图尺寸 */
  background-position: center; /* 背景图位置 */
border-radius: 0px;/*圆角*/

   background-color: rgba(0, 0, 0, 1) !important; /* 黑背景 */
  padding: 3px 5px; /* 内边距 */
  backdrop-filter: blur(15px); /* 背景模糊 */
  -webkit-backdrop-filter: blur(0px); /* Safari兼容 */
  border: 0px solid rgba(0, 0, 0, 1); /* 白色边框 */
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0); /* 无阴影 */
  transition: all 1s ease; /* 过渡动画 */
}


/* 底栏图标间距 */
#rightSendForm, #leftSendForm {
  gap: 5px; /* 图标间距 */
}

/* 输入框样式 */
#send_textarea {
  clip-path: none !important; /* 完整显示输入框 */
  color: #ffffff !important;
  border: none; /* 无边框 */
}

/* === 四、聊天区域美化 === */
/* 聊天区域背景透明 */
#chat {
  background-color: transparent !important; /* 透明背景 */
  backdrop-filter: none !important; /* 无模糊 */
  -webkit-backdrop-filter: none !important; /* Safari兼容 */
  padding: 0 !important; /* 无内边距 */
}

/* 聊天滚动容器透明 */
#chat,
#chat > div,
.chat-scroll-container,
.chat-messages-container {
  background-color: transparent !important; /* 透明背景 */
  background-image: auto !important; /* 无背景图 */
  border: none !important; /* 无边框 */
  outline: none !important; /* 无轮廓 */
}

/* Firefox滚动条兼容 */
.chat-scroll-container {
  scrollbar-color:  transparent !important; /* 透明滚动条 */
}

/*聊天气泡@nini*/

.mes {
    width: 96% !important; /*💖气泡整体宽度*/
    max-width: 100% !important; /* 你可以根据喜好设置一个最大宽度，例如 700px */
    margin-left: 8px !important;/*💖控制白色背景左右*/
    margin-top: 70px !important;/*上下俩条消息距离？*/
    margin-bottom: 10px;
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    overflow: visible !important;
    /* 移除旧的背景和边框，为新的背景图做准备 */
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important; /* 没有圆角 */
    box-shadow: none !important;
    /* --- 关键部分：多重背景 --- */
    background-image: 
        url("https://iili.io/fYh2hq7.png"),  /* 1. 顶部图片 (最上层) */
        url("https://iili.io/fYh2PrF.jpg"),  /* 2. 底部图片 */
        url("https://iili.io/fYh2PrF.jpg"); /* 3. 中间平铺图片 (最底层) */

    background-repeat: 
        no-repeat,      /* 顶部不重复 */
        no-repeat,      /* 底部不重复 */
        repeat-y;       /* 中间沿Y轴(垂直)重复 */
/*❗️这个顺序要和你放图片的顺序一样哦，下面这些调整数据同理*/
    background-position: 
        center top,     /* 顶部图片定位在顶部中央 */
        center bottom,  /* 底部图片定位在底部中央 */
        center center;  /* 中间图片定位在中央 */

    background-size: 
        100% auto,      /* 顶部图片宽度100%，高度自动 */
        100% auto,      /* 底部图片宽度100%，高度自动 */
        100% auto;      /* 中间图片宽度100%，高度自动 */

    /* 
     * [非常重要] 为顶部和底部图片留出足够的内边距空间。
        你可以根据你的图片实际高度微调这两个值，直到效果完美。*/
    padding-top: 10px !important; 
    padding-bottom: 30px !important;
    padding-left: 20px !important;  /* 左右也留出一些边距让信纸效果更好看 */
    padding-right: 0px !important;
}


/* === 头像容器 - 整体控制 === */
.mes .mesAvatarWrapper {
  position: absolute !important; /* 绝对定位，允许自由移动 */
  order: 1; /* 排在文字前面 */
  margin-bottom: 0 !important; /* 移除原有间距 */
  display: block !important; /* 改为block布局，避免flex干扰 */
  padding-bottom: 0 !important; /* 移除原有padding */
  width: var(--pseudo-width, 400px) !important; /* 使用伪元素宽度 */
  height: var(--pseudo-height, 310px) !important; /* 添加高度控制 */
  margin-left: 0 !important; /* 移除自动边距 */
  margin-right: 0 !important; /* 移除自动边距 */
  top: var(--avatar-container-top, 0px) !important; /* 整体垂直位置控制 */
  left: var(--avatar-container-left, 0px) !important; /* 整体水平位置控制 */
  z-index: 1000 !important; /* 较高层级 */
  transform: scale(var(--avatar-container-scale, 1)) !important; /* 整体缩放控制 */
  transform-origin: top left !important; /* 缩放原点 */
}

/* === 头像底部背景图 - 独立控制 === */
.mes .mesAvatarWrapper::after {
  content: '' !important; /* 伪元素必须有content */
  position: absolute !important; /* 绝对定位 */
  top: var(--pseudo-top, 0px) !important; /* 伪元素顶部位置控制 */
  left: var(--pseudo-left, 0px) !important; /* 伪元素水平位置控制 */
  width: var(--pseudo-width, 400px) !important; /* 伪元素宽度控制 */
  height: var(--pseudo-height, 320px) !important; /* 伪元素高度控制 - 使用变量值310px */
  background-image: url('https://iili.io/fYh3ruf.png') !important; /* 🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑背景图，破坏链接可以删除渐变 */
  background-size: cover !important; /* 背景图覆盖 */
  background-position: center !important; /* 背景图居中 */
  background-repeat: no-repeat !important; /* 不重复背景 */
  pointer-events: none !important; /* 点击穿透 */
  z-index: -2 !important; /* 层级低于头像 */
  transform: scale(var(--pseudo-scale, 1)) !important; /* 伪元素缩放控制 */
  transform-origin: top left !important; /* 缩放原点 */
}

/* === 头像外层容器 - 在伪元素内定位 === */
.mes .avatar {
  position: absolute !important; /* 改为绝对定位，在伪元素内定位 */
  z-index: -3 !important; /* 层级高于伪元素 */
  width: 80px !important; /* 头像宽度 */
  height: 80px !important; /* 头像高度 */
  border-radius: 0 !important; /* 无圆角 */
  top: var(--avatar-top, 80%) !important; /* 在伪元素内的垂直位置 - 固定在右下角 */
  left: var(--avatar-left, 50%) !important; /* 在伪元素内的水平位置 */
  transform: translate(-50%, -50%) scale(var(--avatar-scale, 1)) !important; /* 居中和缩放 */
  transform-origin: center !important; /* 缩放原点 */
  box-shadow: 0 0px 0px rgba(0,0,0,0); /* 无阴影 */
  margin: 0 !important; /* 移除所有边距 */
  padding: 0 !important; /* 无内边距 */
  border: none !important; /* 无边框 */
}

/* === 头像图片 === */
.mes .avatar img {
  border-radius: 0 !important; /* 图片无圆角 */
  width: 80px !important; /* 图片宽度 */
  height: 80px !important; /* 图片高度 */
  object-fit: cover !important; /* 图片填充方式 */
  margin: 0 !important; /* 无边距 */
  padding: 0 !important; /* 无内边距 */
  display: block !important; /* 块级显示 */
  aspect-ratio: 1/1 !important; /* 强制宽高比1:1 */
    box-shadow: none !important;
}

/* === 三个信息元素 - 独立控制 === */
.mes_timer, .tokenCounterDisplay, .mesIDDisplay {
  position: absolute !important; /* 绝对定位，允许自由移动 */
  z-index: 1001 !important; /* 确保在最上层 */
  color: #000000 !important; /* 文字颜色 */
  font-size: 10px !important; /* 字体大小 */
  background-color: rgba(0, 0, 0, 0) !important; /* 半透明背景 */
  padding: 0px 0px !important; /* 内边距 */
  border-radius: 0px !important; /* 圆角 */
  transform: scale(var(--info-scale, 1)) !important; /* 缩放控制 */
}

/* 为每个元素单独设置位置 */
.mes_timer {
  top: var(--mes-timer-top, 20px) !important; /* 计时器垂直位置 */
  left: var(--mes-timer-left, 120px) !important; /* 计时器水平位置 */
}

.tokenCounterDisplay {
  top: var(--token-top, 20px) !important; /* Token计数垂直位置 */
  left: var(--token-left, 120px) !important; /* Token计数水平位置 */
}

.mesIDDisplay {
  top: var(--mesid-top, 20px) !important; /* 楼层数垂直位置 */
  left: var(--mesid-left, 220px) !important; /* 楼层数水平位置 */
}

/* === 文字容器调整 === */
.mes .mes_block {
  width: 98% !important; /* 文字区域宽度 */
  text-align: left !important; /* 文字左对齐 */
  text-align: left !important;
  margin: 0 0 0 -15px !important;   /* 💖文本整体位置 */
  padding: 0px !important; /* 内边距 */
  background: transparent !important; /* 透明背景 */
  border-radius: 0px !important; /* 无圆角 */
  position: relative !important; /* 相对定位 */
  z-index: 999 !important; /* 文字层级 */
  margin-top: calc(var(--pseudo-height, 310px) + var(--avatar-container-top, 0px) + 0px) !important; /* 根据伪元素高度和容器位置动态调整间距 */
}


/* 聊天文字容器 */
.mes .mes_text {
  padding: 10px 0 !important; /* 文字上下内边距 */
  width: 100%; /* 文字宽度 */
  font-size: auto !important; /* 文字大小 */
  line-height: 2.0 !important; /* 🛑文字行高 */
}

/* 段落样式 */
.mes_text p {
  margin: 0 0 15px 0 !important; /* 段落间距 */
  padding: 0 !important; /* 无内边距 */
  line-height: 2.0 !important; 
}

/* 🛑三元素样式 */
.mesIDDisplay, .tokenCounterDisplay, .mes_timer {
  color: #000000 !important; /* 文字颜色 */
  font-size: 10px !important; /* 字体大小 */
  margin-bottom: 5px !important; /* 底部间距 */
}

/* 气泡操作按钮 */
.mes_buttons i {
  color: var(--main-text-color) !important; /* 白色图标 */
  font-size: 16px !important; /* 图标大小 */
}

/* 🛑最后一条消息 */
.last_mes {
  padding-bottom: 50px !important; /* 底部间距 */
}

/* 文字样式 */
p, , strong {
  color: var(--main-text-color) !important; /* 白色文字 */
  line-height: 1.8 !important;
}

/* 代码块样式 */
pre {
  background-color: #fff !important; /* 毛玻璃背景 */
  backdrop-filter: blur(5px) !important; /* 背景模糊 */
  -webkit-backdrop-filter: blur(var(--blur-strength)) !important; /* Safari兼容 */
  border: 1px solid #000000 !important; /* 边框 */
  padding: 15px !important; /* 内边距 */
  border-radius: 8px !important; /* 圆角 */
  color: #000000 !important; /* 文字颜色 */
}

pre code {
  color: #000 !important; /* 代码文字颜色 */
  background: none !important; /* 无背景 */
}

:not(pre) > code {
  background-color: #ffffff !important; /* 行内代码背景 */
  backdrop-filter: blur(5px) !important; /* 背景模糊 */
  -webkit-backdrop-filter: blur(var(--blur-strength)) !important; /* Safari兼容 */
  border: 1px solid #000!important; /* 边框 */
  color: #000 !important; /* 文字颜色 */
  padding: 2px 6px; /* 内边距 */
  border-radius: 4px; /* 圆角 */
}

/* 引用样式 */
q {
  background: linear-gradient(to right, #ebebeb 0%, #ebebeb 100%);/*右侧透明就transparent*/
  border: 0px solid #4B86DC;   /* 浅蓝边框，可删 */
  border-radius: 15px;
  padding: 1px 5px;
  color: auto;              /* 深蓝字，更搭 */
  line-height: 1.8 !important;
}

.mesAvatarWrapper .avatar {
  pointer-events: none !important;
}
.swipe_right.swipe_right.swipe_right {
  opacity: 0 !important;
}
