}
/* ===== 标签输入框 ===== */
#tagInput {
    background: rgba(255, 255, 255, 0.3) !important;   /* 白色 0.3 透明度 */
    border: 1px solid #ffffff !important;              /* 白色 1px 实边框 */
    backdrop-filter: blur(15px) !important;            /* 15px 毛玻璃 */
    -webkit-backdrop-filter: blur(15px) !important;
    color: #000000 !important;                         /* 文字颜色 */
    border-radius: 6px !important;                     /* 可选圆角，可调 */
    outline: none !important;
}

/* ===== 正则/脚本条目：毛玻璃统一 ===== */
.regex-script-label.flex-container.flexnowrap {
    background: rgba(255, 255, 255, 0.3) !important;   /* 白色 0.3 透明 */
    border: 1px solid #ffffff !important;              /* 白色 1px 实边框 */
    backdrop-filter: blur(15px) !important;            /* 15px 毛玻璃 */
    -webkit-backdrop-filter: blur(15px) !important;
    color: #000000 !important;                         /* 文字颜色 */
    border-radius: 6px !important;                     /* 圆角，可调 */
    padding: 6px 10px !important;                      /* 内边距，可调 */
    margin: 4px 0 !important;                          /* 条目间距，可调 */
}

/* ====== 通知弹窗2.0 ====== */
#toast-container .toast,
.toast {
    background-color: #fff !important;   /* 纯白底 */
    color: #000000 !important;              /* 黑字 */
    box-shadow: none !important;            /* 去阴影 */
    border: 0px solid #000 !important;   /* 边框 */
    border-radius: 0px !important;         /* 保持圆角 */
    backdrop-filter: none !important;       /* 去毛玻璃（可选） */
    -webkit-backdrop-filter: none !important;
}

/* 强制把里层文字、图标一起改色 */
.toast-message,
.toast-title,
.toast * {
    color: #fff !important;
    -webkit-text-fill-color: #000000 !important;
    text-shadow: none !important;
}
/* ====== 替换 Toast 左侧图标 ====== */
#toast-container > .toast {
    /* 去掉旧图标 */
    background-image: none !important;
    /* 新图标：居中、不重复、给文字留空 */
    background-image: url("https://iili.io/fYhfHrP.png") !important;
    background-size: 32px 32px !important;
    background-repeat: no-repeat !important;
    background-position: 15px center !important;
    /* 左侧留 52 px 给图标，防止文字重叠 */
    padding-left: 52px !important;
}
/* ====== Prompt Manager 单个预设条目去黑底 ====== */
#completion_prompt_manager_list > li.completion_prompt_manager_prompt {
    background: rgba(255, 255, 255, 0.3) !important;   /* 30 % 透明白 */
    backdrop-filter: blur(25px) !important;            /* 25 px 毛玻璃 */
    -webkit-backdrop-filter: blur(25px) !important;
    border: 1px solid #000000 !important;              /* 边框 */
    color: #000000 !important;                         /* 颜色字 */
    border-radius: 6px !important;
}
/* === 未启用的预设条目字变灰 === */
#completion_prompt_manager_list
  li.completion_prompt_manager_prompt_disabled {
    color: #afafaf !important;              /* 颜色 */
}
/* 连带图标、链接、按钮一起改 */
#completion_prompt_manager_list
  li.completion_prompt_manager_prompt_disabled * {
    color: #afafaf !important;
}

/* === Prompt Manager 底板：毛玻璃 + 背景图 === */
#completion_prompt_manager_list.text_pole.ui-sortable {
    /* 玻璃壳 */
    background: rgba(255, 255, 255, 0) !important;
    backdrop-filter: blur(0px) !important;
    -webkit-backdrop-filter: blur(0px) !important;
    border: 0px solid #fff !important;
    border-radius: 8px !important;

    /* 背景图：居中 / 不重复 / 覆盖整个底板 */
    background-image: url("https://你的图片链接.png") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;

    /* 让玻璃色层叠在图上方，防止图太亮 */
    background-blend-mode: overlay !important;
}
/* ✅ 去掉左下角菜单的黑影和毛玻璃 */
#options {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}
/* 菜单文字用手写体，但图标保持 Font Awesome */
#options,
#options *:not(i):not(.fa):not(.fas):not(.far):not(.fal):not(.fab) {
  font-family: "gkai00mp", sans-serif !important;
}
/* ===== text_pole 统一玻璃风（含 API 输入框） ===== */
input.text_pole.wide100p,
input[id="custom_api_url_text"] {
    background: rgba(255, 255, 255, 0.3) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    border: 1px solid #ffffff !important;
    border-radius: 25px !important;
    color: #000000 !important;          /* 深蓝字，随系统可改 inherit */
    padding: 6px 12px !important;
    outline: none !important;
}
.mes_text p {
  text-indent: 2em;  /* 缩进距离 */
}
